$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'OrchestrationEventAdmissionSlowPath.ps1')
$script:count=0
function A($v,$m){$script:count++;if(!$v){throw "FAIL: $m"}}
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path
$real=Import-OrchestrationEventAdmissionSlowPathPolicy -RepoRoot $root;A ($real.ok -and !$real.policy.enabled) 'default disabled'
$tmp=Join-Path ([IO.Path]::GetTempPath()) ([guid]::NewGuid().ToString('N'));$target=Join-Path $tmp 'target';[void](New-Item -ItemType Directory $target);$link=Join-Path $tmp 'link';$linked=$false
try{
 $base=@{schema_version=1;policy_version='1';enabled=$true;min_confidence=0.7;max_summary_chars=20;max_rationale_chars=12;max_requests_per_day=2;max_requests_per_thread=2;classes=@('candidate','context_only','ignore')}
 function Write-Policy($doc){$p=Join-Path $tmp (([guid]::NewGuid().ToString('N'))+'.json');[IO.File]::WriteAllText($p,(ConvertTo-Json -InputObject $doc -Depth 8 -Compress),[Text.UTF8Encoding]::new($false));return $p}
 $path=Write-Policy $base;$loaded=Import-OrchestrationEventAdmissionSlowPathPolicy $path;A $loaded.ok 'valid policy'
 A ((Import-OrchestrationEventAdmissionSlowPathPolicy (Join-Path $tmp 'missing.json')).error -eq 'SLOWPATH_POLICY_PATH_NOT_FOUND') 'missing policy'
 $mal=Join-Path $tmp 'malformed.json';[IO.File]::WriteAllText($mal,'{');A ((Import-OrchestrationEventAdmissionSlowPathPolicy $mal).error -eq 'SLOWPATH_POLICY_INVALID_JSON') 'invalid json'
 $big=Join-Path $tmp 'big.json';[IO.File]::WriteAllText($big,(' '*20));A ((Import-OrchestrationEventAdmissionSlowPathPolicy $big -MaxBytes 10).error -eq 'SLOWPATH_POLICY_TOO_LARGE') 'max bytes'
 foreach($sv in @('"1"','1.0')){$bad=Join-Path $tmp 'schema.json';$doc=ConvertTo-Json -InputObject $base -Compress;$doc=$doc -replace '"schema_version":1',('"schema_version":'+$sv);[IO.File]::WriteAllText($bad,$doc);A ((Import-OrchestrationEventAdmissionSlowPathPolicy $bad).error -eq 'SLOWPATH_POLICY_SCHEMA_INVALID') ('schema type '+$sv)}
 $d=[ordered]@{};foreach($k in $base.Keys){if($k -cne 'min_confidence'){$d[$k]=$base[$k]}};A ((Import-OrchestrationEventAdmissionSlowPathPolicy (Write-Policy $d)).error -eq 'SLOWPATH_POLICY_SCHEMA_INVALID') 'missing required key'
 $d=$base.Clone();$d.extra=1;A ((Import-OrchestrationEventAdmissionSlowPathPolicy (Write-Policy $d)).error -eq 'SLOWPATH_POLICY_SCHEMA_INVALID') 'unknown policy key'
 foreach($classes in @(@('candidate','candidate'),@('candidate','bogus'))){$d=$base.Clone();$d.classes=$classes;A ((Import-OrchestrationEventAdmissionSlowPathPolicy (Write-Policy $d)).error -eq 'SLOWPATH_POLICY_SCHEMA_INVALID') 'invalid classes'}
 foreach($conf in @(1.1,$true)){$d=$base.Clone();$d.min_confidence=$conf;A ((Import-OrchestrationEventAdmissionSlowPathPolicy (Write-Policy $d)).error -eq 'SLOWPATH_POLICY_SCHEMA_INVALID') 'invalid policy confidence'}
 [IO.File]::WriteAllText((Join-Path $target 'policy.json'),(ConvertTo-Json -InputObject $base -Compress),[Text.UTF8Encoding]::new($false));New-Item -ItemType Junction -Path $link -Target $target|Out-Null;$linked=$true;A ((Import-OrchestrationEventAdmissionSlowPathPolicy (Join-Path $link 'policy.json')).error -eq 'SLOWPATH_POLICY_PATH_INVALID') 'junction rejected'
 $e=New-OrchestrationEventEnvelope github issue_comment pr:12 delivery-1 a/b -Summary 'secret=foo and more than twenty chars';$c=@{actor_type='human';source_allowlisted=$true;blocklisted=$false;duplicate=$false};$f=@{ok=$true;intent='context_only';signals=@('ambiguous')};$usage=@{requests_today=1;requests_for_thread=1};$pol=$loaded.policy
 $req=Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage;A ($req.decision -eq 'request' -and $req.request.request_digest -match '^[0-9a-f]{64}$') 'request digest';A ($req.request.summary.Length -le 20 -and $req.request.summary.Contains('[REDACTED]')) 'redacted and truncated';$serial=ConvertTo-Json $req -Compress;for($i=0;$i -lt 2;$i++){A ((ConvertTo-Json (Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage) -Compress) -ceq $serial) 'request deterministic'}
 foreach($intent in @('explicit','candidate','ignore')){$x=$f.Clone();$x.intent=$intent;A ((Request-OrchestrationEventAdmissionSlowPath $e $c $x $pol $usage).reason -eq ('not-ambiguous:'+$intent)) ('intent '+$intent)}
 $c.actor_type='bot';A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage).reason -eq 'bot') 'bot';$c.actor_type='human';$c.blocklisted=$true;A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage).reason -eq 'blocklisted') 'blocklist';$c.blocklisted=$false;$c.duplicate=$true;A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage).reason -eq 'duplicate') 'duplicate';$c.duplicate=$false
 $ei=$e.Clone();$ei.informational_only=$true;A ((Request-OrchestrationEventAdmissionSlowPath $ei $c $f $pol $usage).reason -eq 'informational-only') 'informational';$c.source_allowlisted=$false;A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage).reason -eq 'source-not-allowlisted') 'source allowlist';$c.source_allowlisted=$true;$c.actor_type='unknown';A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage).reason -eq 'unknown-actor') 'unknown actor';$c.actor_type='service';A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage).reason -eq 'non-human-actor') 'non-human actor';$c.actor_type='human'
 A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $null).reason -eq 'usage-cap') 'usage absent';$usage.requests_today=0;$usage.requests_for_thread=0;A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage).decision -eq 'request') 'cap minus one';$usage.requests_today=2;A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage).reason -eq 'usage-cap') 'daily cap';$usage.requests_today=0;$usage.requests_for_thread=2;A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $pol $usage).reason -eq 'usage-cap') 'thread cap'
 $usage.requests_for_thread=0;$usage.requests_today=0;$noKey=@{source='github';trigger='issue_comment';thread='pr:12';repo='a/b';summary='s';informational_only=$false};A ((Request-OrchestrationEventAdmissionSlowPath $noKey $c $f $pol $usage).reason -eq 'invalid-envelope') 'missing dedup';A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $null $usage).reason -eq 'invalid-policy') 'null policy';A ((Request-OrchestrationEventAdmissionSlowPath $e $c $f $real.policy $usage).reason -eq 'policy-disabled') 'policy disabled'
 $baseResponse=@{request_digest=$req.request.request_digest;classification='candidate';confidence=0.9;rationale='ok'};$valid=Test-OrchestrationEventAdmissionSlowPathResponse $req.request ([pscustomobject]$baseResponse) $pol;A ($valid.ok -and $valid.action -eq 'would_new_task' -and !$valid.executable) 'candidate shadow'
 foreach($bad in @(@{confidence=1.1},@{confidence=-0.1},@{confidence='0.9'},@{confidence=$true})){$r=$baseResponse.Clone();foreach($k in $bad.Keys){$r[$k]=$bad[$k]};A ((Test-OrchestrationEventAdmissionSlowPathResponse $req.request $r $pol).error -eq 'SLOWPATH_CONFIDENCE_INVALID') 'response confidence'}
 $r=$baseResponse.Clone();$r.rationale='rationale is oversized';A ((Test-OrchestrationEventAdmissionSlowPathResponse $req.request $r $pol).error -eq 'SLOWPATH_RATIONALE_INVALID') 'rationale limit';$r=$baseResponse.Clone();$r.provider=('x'*101);A ((Test-OrchestrationEventAdmissionSlowPathResponse $req.request $r $pol).error -eq 'SLOWPATH_METADATA_INVALID') 'metadata limit';$r=$baseResponse.Clone();$r.classification=4;A ((Test-OrchestrationEventAdmissionSlowPathResponse $req.request $r $pol).error -eq 'SLOWPATH_CLASS_INVALID') 'classification type';$r=$baseResponse.Clone();$r.extra=1;A ((Test-OrchestrationEventAdmissionSlowPathResponse $req.request $r $pol).error -eq 'SLOWPATH_RESPONSE_INVALID') 'extra response field'
 $r=$baseResponse.Clone();$r.request_digest=('0'*64);A ((Test-OrchestrationEventAdmissionSlowPathResponse $req.request $r $pol).error -eq 'SLOWPATH_DIGEST_MISMATCH') 'response digest';$r=$baseResponse.Clone();$r.confidence=0.2;$low=Test-OrchestrationEventAdmissionSlowPathResponse $req.request $r $pol;A ($low.ok -and $low.intent -eq 'context_only' -and $low.reason -eq 'low-confidence') 'low confidence'
 $dict=[ordered]@{};foreach($p in $req.request.PSObject.Properties){$dict[$p.Name]=$p.Value};$r=$baseResponse.Clone();A ((Test-OrchestrationEventAdmissionSlowPathResponse $dict $r $pol).ok) 'ordered hashtable request digest';$extra=[ordered]@{};foreach($k in $dict.Keys){$extra[$k]=$dict[$k]};$extra.extra='spoof';A ((Test-OrchestrationEventAdmissionSlowPathResponse $extra $r $pol).error -eq 'SLOWPATH_DIGEST_MISMATCH') 'extra request field invalidates digest'
 foreach($class in @('ignore','context_only')){$r=$baseResponse.Clone();$r.classification=$class;$x=Test-OrchestrationEventAdmissionSlowPathResponse $req.request $r $pol;$expected=if($class -eq 'ignore'){'ignore'}else{'observe'};A ($x.ok -and $x.action -eq $expected -and !$x.executable) ('response '+$class)}
 # CLI round-trip: preserve each process's exact stdout for byte determinism.
 $cli=Join-Path $root 'scripts/v3/event-admission-slow-path.ps1';$policyFile=Write-Policy $base;$envFile=Join-Path $tmp 'envelope.json';$ctxFile=Join-Path $tmp 'context.json';$fastFile=Join-Path $tmp 'fast.json';$usageFile=Join-Path $tmp 'usage.json';$reqFile=Join-Path $tmp 'request.json';$respFile=Join-Path $tmp 'response.json'
 [IO.File]::WriteAllText($envFile,(ConvertTo-Json $e -Compress));[IO.File]::WriteAllText($ctxFile,(ConvertTo-Json $c -Compress));[IO.File]::WriteAllText($fastFile,(ConvertTo-Json $f -Compress));[IO.File]::WriteAllText($usageFile,(ConvertTo-Json $usage -Compress))
 $exe=(Get-Process -Id $PID).Path;$cliArgs=@('-NoProfile','-File',$cli,'-Action','request','-EnvelopeFile',$envFile,'-ContextFile',$ctxFile,'-FastFile',$fastFile,'-PolicyFile',$policyFile,'-UsageFile',$usageFile);$out1=(& $exe @cliArgs|Out-String).Trim();A ($LASTEXITCODE -eq 0 -and ((ConvertFrom-Json $out1).executable -eq $false)) 'CLI request';$out2=(& $exe @cliArgs|Out-String).Trim();A ($LASTEXITCODE -eq 0 -and $out1 -ceq $out2) 'CLI deterministic'
 [IO.File]::WriteAllText($reqFile,(ConvertTo-Json (ConvertFrom-Json $out1).request -Compress));$cliReq=ConvertFrom-Json ([IO.File]::ReadAllText($reqFile));$response=[ordered]@{request_digest=$cliReq.request_digest;classification='candidate';confidence=0.9;rationale='ok'};[IO.File]::WriteAllText($respFile,(ConvertTo-Json $response -Compress));$evalOut=(& $exe -NoProfile -File $cli -Action evaluate -RequestFile $reqFile -ResponseFile $respFile -PolicyFile $policyFile|Out-String).Trim();A ($LASTEXITCODE -eq 0 -and (ConvertFrom-Json $evalOut).ok) 'CLI evaluate roundtrip'
 $badPolicy=Join-Path $tmp 'bad-policy.json';[IO.File]::WriteAllText($badPolicy,'{}');$badOut=(& $exe -NoProfile -File $cli -Action request -EnvelopeJson '{}' -ContextJson '{}' -FastJson '{}' -PolicyFile $badPolicy|Out-String).Trim();A ($LASTEXITCODE -eq 1 -and !(ConvertFrom-Json $badOut).ok) 'CLI policy invalid'
 $savedPreference=$ErrorActionPreference;$ErrorActionPreference='Continue';foreach($cliArgsBad in @(@('-Action','request'),@('-Action','request','-EnvelopeFile',$envFile,'-EnvelopeJson','{}','-ContextJson','{}','-FastJson','{}'),@('-Action','bogus'))){& $exe -NoProfile -File $cli @cliArgsBad *> $null;A ($LASTEXITCODE -eq 2) 'CLI usage exit'};$ErrorActionPreference=$savedPreference
}finally{if($linked){[IO.Directory]::Delete($link)};Remove-Item -LiteralPath $tmp -Recurse -Force}
Write-Host "PASS OrchestrationEventAdmissionSlowPath $script:count assertions"
